import{_ as c,o,c as d,a0 as a}from"./chunks/framework.Bb-2yHh0.js";const s="/xv6-book-zh/assets/mkernel.EGfBX_yG.png",p="/xv6-book-zh/assets/as.kEnD6ofR.png",n="/xv6-book-zh/assets/astmp.3HW00_uO.png",t="/xv6-book-zh/assets/newkernelstack.Djo33OX5.png",u=JSON.parse('{"title":"第 1 章 操作系统组织","description":"","frontmatter":{"title":"第 1 章 操作系统组织","outline":[2,3]},"headers":[],"relativePath":"ch1.md","filePath":"ch1.md"}'),i={name:"ch1.md"};function r(l,e,h,f,x,g){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="第-1-章-操作系统组织" tabindex="-1">第 1 章　操作系统组织 <a class="header-anchor" href="#第-1-章-操作系统组织" aria-label="Permalink to &quot;第 1 章　操作系统组织&quot;">​</a></h1><p>操作系统的一项关键需求是同时支持多项活动。例如，使用 <a href="./ch0">第 0 章</a> 介绍的系统调用接口，进程可以用 <code>fork</code> 启动新进程。操作系统必须在这些进程之间对计算机的资源进行<em>分时</em>。例如，即使进程数量多于硬件处理器的数量，操作系统也必须确保所有进程都能取得进展。操作系统还必须安排进程之间的<em>隔离</em>。也就是说，如果一个进程有缺陷并失败，它不应影响那些不依赖该失败进程的进程。然而，完全隔离又太强了，因为进程之间应当能够交互；管道就是一个例子。因此，操作系统必须满足三项要求：多路复用、隔离和交互。</p><p>本章概述操作系统如何组织起来以满足这三项要求。实现方式有很多，但本文关注以<em>宏内核</em>为中心的主流设计，许多 Unix 操作系统都采用这种设计。本章通过追踪 xv6 启动时第一个进程的创建过程来介绍 xv6 的设计。在此过程中，本文会展示 xv6 提供的所有主要抽象的实现、它们如何相互作用，以及多路复用、隔离和交互这三项要求如何得到满足。xv6 的大部分代码都避免为第一个进程做特殊处理，而是复用 xv6 为常规运行必须提供的代码。后续各章将更详细地探讨每一种抽象。</p><p>xv6 运行在 PC 平台的 Intel 80386 或更高（“x86”）处理器上，它的许多底层功能（例如进程的实现）是 x86 特有的。本书假定读者已在某种体系结构上做过一些机器级编程，并会在需要时介绍 x86 特有的概念。附录简要概述了 PC 平台。</p><h2 id="ch1-s1" tabindex="-1">抽象物理资源 <a class="header-anchor" href="#ch1-s1" aria-label="Permalink to &quot;抽象物理资源 {#ch1-s1}&quot;">​</a></h2><p>遇到一个操作系统时，人们可能首先会问：为什么要有它？也就是说，人们可以把 <a class="figref" href="./ch0#fig-api">图 0-2</a> 中的系统调用实现为一个库，让应用程序链接它。在这种方案中，每个应用程序甚至可以拥有为自己需求量身定制的库。应用程序可以直接与硬件资源交互，并以对应用程序最有利的方式使用这些资源（例如获得高而可预测的性能）。一些面向嵌入式设备或实时系统的操作系统就是这样组织的。</p><p>这种库方式的缺点在于，如果有多个应用程序在运行，它们必须行为良好。例如，每个应用程序都必须定期让出处理器，以便其他应用程序运行。如果所有应用程序互相信任且没有缺陷，这种<em>协作式</em>分时方案也许可行。更常见的情况是应用程序互不信任且有缺陷，因此人们往往希望获得比协作式方案更强的隔离。</p><p>要实现强隔离，有帮助的做法是禁止应用程序直接访问敏感的硬件资源，转而把资源抽象为服务。例如，应用程序只通过 <code>open</code>、<code>read</code>、<code>write</code> 和 <code>close</code> 系统调用与文件系统交互，而不是读写原始磁盘扇区。这为应用程序提供了路径名的便利，也使操作系统（作为接口的实现者）能够管理磁盘。</p><p>类似地，Unix 在进程之间透明地切换硬件处理器，必要时保存和恢复寄存器状态，使应用程序无需感知分时。这种透明性使操作系统即使在某些应用程序陷入无限循环时也能共享处理器。</p><p>再举一个例子，Unix 进程使用 <code>exec</code> 构建其内存映像，而不是直接与物理内存交互。这使操作系统可以决定把进程放在内存的什么位置；如果内存紧张，操作系统甚至可以把进程的部分数据存到磁盘上。<code>Exec</code> 还为用户提供了用文件系统存储可执行程序映像的便利。</p><p>Unix 进程之间的许多交互形式都通过文件描述符进行。文件描述符不仅抽象掉了许多细节（例如管道或文件中的数据存放在哪里），它们的定义方式还简化了交互。例如，如果管道中的一个应用程序失败，内核会为管道中的下一个进程产生文件结束。</p><p>如你所见，<a class="figref" href="./ch0#fig-api">图 0-2</a> 中的系统调用接口经过精心设计，既为程序员提供便利，又使强隔离成为可能。Unix 接口并不是抽象资源的唯一方式，但它已被证明是一种非常好的方式。</p><h2 id="ch1-s2" tabindex="-1">用户模式、内核模式与系统调用 <a class="header-anchor" href="#ch1-s2" aria-label="Permalink to &quot;用户模式、内核模式与系统调用 {#ch1-s2}&quot;">​</a></h2><p>强隔离要求应用程序与操作系统之间有一条硬边界。如果应用程序犯了错误，我们不希望操作系统失败，也不希望其他应用程序失败。相反，操作系统应当能够清理失败的应用程序并继续运行其他应用程序。要实现强隔离，操作系统必须安排应用程序不能修改（甚至不能读取）操作系统的数据结构和指令，并且应用程序不能访问其他进程的内存。</p><p>处理器为强隔离提供硬件支持。例如，x86 处理器与许多其他处理器一样，有两种执行指令的模式：<em>内核模式</em>和<em>用户模式</em>。在内核模式下，处理器被允许执行<em>特权指令</em>。例如，读写磁盘（或任何其他 I/O 设备）涉及特权指令。如果用户模式下的应用程序试图执行特权指令，处理器不会执行该指令，而是切换到内核模式，以便内核模式下的软件清理该应用程序，因为它做了不该做的事。<a href="./ch0">第 0 章</a> 中的 <a class="figref" href="./ch0#fig-os">图 0-1</a> 说明了这种组织方式。应用程序只能执行用户模式指令（例如加法等），称为运行在<em>用户空间</em>；而内核模式下的软件还可以执行特权指令，称为运行在<em>内核空间</em>。运行在内核空间（或内核模式）的软件称为<em>内核</em>。</p><p>想要读写磁盘文件的应用程序必须转入内核才能做到，因为应用程序本身不能执行 I/O 指令。处理器提供了一条特殊指令，把处理器从用户模式切换到内核模式，并在内核指定的入口点进入内核。（x86 处理器为此提供了 <code>int</code> 指令。）处理器切换到内核模式后，内核就可以验证系统调用的参数，判定是否允许应用程序执行所请求的操作，然后拒绝或执行它。内核设定进入内核模式的入口点，这一点很重要；如果应用程序能够决定内核入口点，恶意应用程序就可以从一个跳过参数验证等步骤的位置进入内核。</p><h2 id="ch1-s3" tabindex="-1">内核组织 <a class="header-anchor" href="#ch1-s3" aria-label="Permalink to &quot;内核组织 {#ch1-s3}&quot;">​</a></h2><p>一个关键的设计问题是：操作系统的哪一部分应当运行在内核模式下。一种可能是整个操作系统都驻留在内核中，因而所有系统调用的实现都运行在内核模式下。这种组织方式称为<em>宏内核</em>。</p><p>在这种组织方式中，整个操作系统都以完整的硬件特权运行。这种组织方式很方便，因为操作系统设计者不必决定操作系统的哪一部分不需要完整的硬件特权。此外，操作系统的不同部分很容易协作。例如，操作系统可以有一个缓冲区缓存，同时供文件系统和虚拟内存系统共享。</p><p>宏内核组织方式的缺点是，操作系统不同部分之间的接口往往很复杂（我们将在本书余下部分看到这一点），因此操作系统开发者很容易犯错。在宏内核中，错误是致命的，因为内核模式下的错误往往会导致内核失败。如果内核失败，计算机就停止工作，因而所有应用程序也都失败。计算机必须重启才能再次启动。</p><p>为了降低内核中出错的风险，操作系统设计者可以尽量减少运行在内核模式下的操作系统代码量，而把操作系统的主体放在用户模式下执行。这种内核组织方式称为<em>微内核</em>。</p><figure class="xv6-fig" id="fig-mkernel"><img src="'+s+'" alt="带文件系统服务器的微内核" loading="lazy"><figcaption><span class="fig-no">图 1-1</span>带文件系统服务器的微内核</figcaption></figure><p><a class="figref" href="#fig-mkernel">图 1-1</a> 说明了这种微内核设计。图中，文件系统作为用户级进程运行。作为进程运行的操作系统服务称为服务器。为了让应用程序能够与文件服务器交互，内核提供了一种进程间通信机制，用于把一个用户模式进程的消息发送给另一个用户模式进程。例如，如果像 shell 这样的应用程序想要读写文件，它就向文件服务器发送一条消息，并等待响应。</p><p>在微内核中，内核接口由少量底层函数组成，用于启动应用程序、发送消息、访问设备硬件等。这种组织方式使内核可以相对简单，因为操作系统的大部分都驻留在用户级服务器中。</p><p>xv6 按照大多数 Unix 操作系统的做法，实现为宏内核。因此，在 xv6 中，内核接口就对应操作系统接口，内核实现了完整的操作系统。由于 xv6 提供的服务不多，它的内核比一些微内核还要小。</p><h2 id="ch1-s4" tabindex="-1">进程概述 <a class="header-anchor" href="#ch1-s4" aria-label="Permalink to &quot;进程概述 {#ch1-s4}&quot;">​</a></h2><p>xv6 中（与其他 Unix 操作系统一样）的隔离单位是<em>进程</em>。进程抽象防止一个进程破坏或窥探另一个进程的内存、CPU、文件描述符等。它还防止进程破坏内核本身，使进程无法颠覆内核的隔离机制。内核必须谨慎地实现进程抽象，因为有缺陷或恶意的应用程序可能诱使内核或硬件做出坏事（例如绕过强制的隔离）。内核用来实现进程的机制包括用户/内核模式标志、地址空间以及线程的时间片轮转。</p><p>为了帮助实施隔离，进程抽象为程序提供一种幻觉：它拥有自己私有的机器。进程为程序提供一个看似私有的内存系统，即<em>地址空间</em>，其他进程不能读写它。进程还为程序提供一个看似属于自己的 CPU，用来执行程序的指令。</p><p>xv6 使用页表（由硬件实现）为每个进程提供自己的地址空间。x86 页表把<em>虚拟地址</em>（x86 指令操作的地址）转换（或“映射”）为<em>物理地址</em>（处理器芯片发送给主存的地址）。</p><figure class="xv6-fig" id="fig-as"><img src="'+p+'" alt="虚拟地址空间的布局" loading="lazy"><figcaption><span class="fig-no">图 1-2</span>虚拟地址空间的布局</figcaption></figure><p>xv6 为每个进程维护一张单独的页表，用以定义该进程的地址空间。如 <a class="figref" href="#fig-as">图 1-2</a> 所示，地址空间包含从虚拟地址零开始的进程<em>用户内存</em>。指令排在最前面，接着是全局变量，然后是栈，最后是一块“堆”区域（供 malloc 使用），进程可以按需扩展它。</p><p>每个进程的地址空间既映射用户程序的内存，也映射内核的指令和数据。当进程调用系统调用时，系统调用在该进程地址空间的内核映射中执行。这样安排是为了让内核的系统调用代码能够直接引用用户内存。为了给用户内存留出充足的空间，xv6 的地址空间把内核映射在高地址处，起始于 <code>0x80100000</code>。</p><p>xv6 内核为每个进程维护许多状态，并把它们汇集到一个 <code>struct proc</code> <span class="ln">(2337)</span> 中。进程最重要的内核状态是它的页表、内核栈和运行状态。我们将用 <code>p-&gt;xxx</code> 这种写法来引用 <code>proc</code> 结构中的成员。</p><p>每个进程都有一个执行线程（简称<em>线程</em>），执行该进程的指令。线程可以被挂起，稍后再恢复。为了在进程之间透明地切换，内核挂起当前正在运行的线程，并恢复另一个进程的线程。线程的许多状态（局部变量、函数调用的返回地址）保存在线程的栈上。每个进程有两个栈：用户栈和内核栈（<code>p-&gt;kstack</code>）。当进程执行用户指令时，只有用户栈在使用，内核栈是空的。当进程进入内核（因系统调用或中断）时，内核代码在该进程的内核栈上执行；进程处于内核中时，其用户栈仍然保存着数据，但并未被积极使用。进程的线程在积极使用用户栈和内核栈之间交替。内核栈是独立的（并且对用户代码受保护），这样即使进程破坏了自己的用户栈，内核仍能执行。</p><p>当进程发起系统调用时，处理器切换到内核栈，提升硬件特权级，并开始执行实现该系统调用的内核指令。系统调用完成后，内核返回用户空间：硬件降低特权级，切回用户栈，并在系统调用指令之后恢复执行用户指令。进程的线程可以在内核中“阻塞”以等待 I/O，并在 I/O 完成后从离开的地方继续。</p><p><code>p-&gt;state</code> 指示进程是已分配、可运行、正在运行、等待 I/O，还是正在退出。</p><p><code>p-&gt;pgdir</code> 保存进程的页表，格式是 x86 硬件所期望的。xv6 在执行某个进程时，会让分页硬件使用该进程的 <code>p-&gt;pgdir</code>。进程的页表同时也是记录：哪些物理页被分配用来存放该进程的内存。</p><h2 id="ch1-s5" tabindex="-1">代码：第一个地址空间 <a class="header-anchor" href="#ch1-s5" aria-label="Permalink to &quot;代码：第一个地址空间 {#ch1-s5}&quot;">​</a></h2><p>为了让 xv6 的组织方式更具体，我们来看内核如何创建第一个地址空间（为它自己），内核如何创建并启动第一个进程，以及该进程如何执行第一次系统调用。通过追踪这些操作，我们能够详细看到 xv6 如何为进程提供强隔离。提供强隔离的第一步，是让内核运行在自己的地址空间中。</p><p>PC 加电时会自我初始化，然后从磁盘把一个<em>引导加载器</em>装入内存并执行它。附录会解释其中的细节。xv6 的引导加载器从磁盘加载 xv6 内核，并从 <code>entry</code> <span class="ln">(1044)</span> 开始执行它。内核启动时 x86 分页硬件尚未启用；虚拟地址直接映射到物理地址。</p><p>引导加载器把 xv6 内核装入物理地址 <code>0x100000</code> 处的内存。它之所以不把内核装入内核期望找到其指令和数据的位置，是因为小型机器上如此高的地址处可能根本没有物理内存。它之所以把内核放在 <code>0x100000</code> 而不是 <code>0x0</code>，是因为地址范围 <code>0xa0000:0x100000</code> 包含 I/O 设备。</p><figure class="xv6-fig" id="fig-astmp"><img src="'+n+'" alt="虚拟地址空间的布局" loading="lazy"><figcaption><span class="fig-no">图 1-3</span>虚拟地址空间的布局</figcaption></figure><p>为了让内核的其余部分得以运行，<code>entry</code> 建立了一张页表，把从 <code>0x80000000</code>（称为 <code>KERNBASE</code> <span class="ln">(0207)</span>）开始的虚拟地址映射到从 <code>0x0</code> 开始的物理地址（见 <a class="figref" href="#fig-as">图 1-2</a>）。建立两段映射到同一物理内存范围的虚拟地址，是页表的一种常见用法，我们还会看到更多类似的例子。</p><p>这张入口页表定义在 main.c 中。我们将在 <a href="./ch2">第 2 章</a> 详细讨论页表的细节，但简要地说，第 0 项把虚拟地址 <code>0:0x400000</code> 映射到物理地址 <code>0:0x400000</code>。只要 <code>entry</code> 还在低地址处执行，这个映射就是必需的，但最终会被移除。</p><p>第 512 项把虚拟地址 <code>KERNBASE:KERNBASE+0x400000</code> 映射到物理地址 <code>0:0x400000</code>。内核在 <code>entry</code> 完成后将使用这一项；它把内核期望找到其指令和数据的高虚拟地址，映射到引导加载器装入它们时的低物理地址。这个映射把内核的指令和数据限制在 4 MB 以内。</p><p>回到 <code>entry</code>，它把 <code>entrypgdir</code> 的物理地址装入控制寄存器 <code>cr3</code>。<code>cr3</code> 中的值必须是物理地址。让 <code>cr3</code> 保存 <code>entrypgdir</code> 的虚拟地址是说不通的，因为分页硬件还不知道如何转换虚拟地址；它还没有页表。符号 <code>entrypgdir</code> 指的是高内存中的一个地址，宏 <code>V2P_WO</code> 减去 <code>KERNBASE</code> 以求出物理地址。为了启用分页硬件，xv6 在控制寄存器 <code>cr0</code> 中设置 <code>CR0_PG</code> 标志。</p><p>启用分页之后，处理器仍在低地址处执行指令，这之所以可行，是因为 <code>entrypgdir</code> 映射了低地址。如果 xv6 从 <code>entrypgdir</code> 中去掉第 0 项，那么在试图执行启用分页那条指令之后的下一条指令时，计算机就会崩溃。</p><p>现在 <code>entry</code> 需要转入内核的 C 代码，并在高内存中运行它。首先，它让栈指针 <code>esp</code> 指向用作栈的内存 <span class="ln">(1058)</span>。所有符号都具有高地址，包括 <code>stack</code>，因此即使低地址映射被移除，栈仍然有效。最后，<code>entry</code> 跳转到 <code>main</code>，它也是一个高地址。这里需要间接跳转，因为否则汇编器会生成 PC 相对的直接跳转，那将执行低内存版本的 <code>main</code>。<code>Main</code> 不能返回，因为栈上没有返回 PC。现在内核正在高地址处、在函数 <code>main</code> <span class="ln">(1217)</span> 中运行。</p><h2 id="ch1-s6" tabindex="-1">代码：创建第一个进程 <a class="header-anchor" href="#ch1-s6" aria-label="Permalink to &quot;代码：创建第一个进程 {#ch1-s6}&quot;">​</a></h2><p>现在我们来看内核如何创建用户级进程，并确保它们被强隔离。</p><p><code>main</code> <span class="ln">(1217)</span> 初始化若干设备和子系统之后，通过调用 <code>userinit</code> <span class="ln">(2520)</span> 创建第一个进程。<code>Userinit</code> 的第一个动作是调用 <code>allocproc</code>。<code>allocproc</code> <span class="ln">(2473)</span> 的任务是在进程表中分配一个槽位（一个 <code>struct</code> <code>proc</code>），并初始化进程状态中内核线程执行所需的部分。<code>Allocproc</code> 会为每个新进程调用，而 <code>userinit</code> 只为第一个进程调用。<code>Allocproc</code> 扫描 <code>proc</code> 表，寻找状态为 <code>UNUSED</code> 的槽位 <span class="ln">(2480-2482)</span>。找到未使用的槽位后，<code>allocproc</code> 把状态设为 <code>EMBRYO</code> 以标记它已被使用，并给该进程分配一个唯一的 <code>pid</code> <span class="ln">(2469-2489)</span>。接下来，它尝试为该进程的内核线程分配一个内核栈。如果内存分配失败，<code>allocproc</code> 把状态改回 <code>UNUSED</code> 并返回零以示失败。</p><figure class="xv6-fig" id="fig-newkernelstack"><img src="'+t+'" alt="新的内核栈。" loading="lazy"><figcaption><span class="fig-no">图 1-4</span>新的内核栈。</figcaption></figure><p>现在 <code>allocproc</code> 必须建立新进程的内核栈。<code>allocproc</code> 的写法使它既能用于 <code>fork</code>，也能用于创建第一个进程。<code>allocproc</code> 为新进程准备一个特殊构造的内核栈和一组内核寄存器，使新进程首次运行时“返回”到用户空间。所准备的内核栈的布局如 <a class="figref" href="#fig-newkernelstack">图 1-4</a> 所示。<code>allocproc</code> 完成其中一部分工作：设置返回的程序计数器值，使新进程的内核线程先执行 <code>forkret</code>，然后执行 <code>trapret</code> <span class="ln">(2507-2512)</span>。内核线程将使用从 <code>p-&gt;context</code> 复制的寄存器内容开始执行。因此，把 <code>p-&gt;context-&gt;eip</code> 设为 <code>forkret</code> 将使内核线程从 <code>forkret</code> <span class="ln">(2853)</span> 的开头开始执行。这个函数将返回到栈底处的地址。上下文切换代码把栈指针设置为刚好越过 <code>p-&gt;context</code> 末尾的位置。<code>allocproc</code> 把 <code>p-&gt;context</code> 放在栈上，并在它上面放一个指向 <code>trapret</code> 的指针；<code>forkret</code> 就将返回到那里。<code>trapret</code> 从内核栈顶存储的值恢复用户寄存器，并跳入进程 <span class="ln">(3324)</span>。这一设置对普通的 <code>fork</code> 和创建第一个进程是相同的，只不过在后一种情况下，进程将从用户空间的地址零开始执行，而不是从 <code>fork</code> 返回处开始。</p><p>正如我们将在 <a href="./ch3">第 3 章</a> 看到的，控制从用户软件转移到内核的方式是通过中断机制，系统调用、中断和异常都使用它。每当进程运行期间控制转入内核时，硬件和 xv6 的陷阱入口代码都会把用户寄存器保存在该进程的内核栈上。<code>userinit</code> 在新栈顶写入的值，看起来就像进程通过中断进入内核时栈上会有的值 <span class="ln">(2533-2539)</span>，这样从内核返回进程用户代码的常规代码就能正常工作。这些值构成一个 <code>struct trapframe</code>，用来保存用户寄存器。现在，新进程的内核栈已完全准备好，如 <a class="figref" href="#fig-newkernelstack">图 1-4</a> 所示。</p><p>第一个进程将要执行一个小程序（<code>initcode.S</code>；<span class="ln">(8400)</span>）。该进程需要物理内存来存放这个程序，程序需要被复制到那块内存，进程还需要一张把用户空间地址映射到那块内存的页表。</p><p><code>userinit</code> 调用 <code>setupkvm</code> <span class="ln">(1818)</span> 为进程创建页表，起初只映射内核使用的内存。我们将在 <a href="./ch2">第 2 章</a> 详细研究这个函数，但概括地说，<code>setupkvm</code> 和 <code>userinit</code> 创建的地址空间如 <a class="figref" href="#fig-as">图 1-2</a> 所示。</p><p>第一个进程用户空间内存的初始内容是 <code>initcode.S</code> 的编译产物；作为内核构建过程的一部分，链接器把该二进制嵌入内核，并定义两个特殊符号 <code>_binary_initcode_start</code> 和 <code>_binary_initcode_size</code>，指明该二进制的位置和大小。<code>Userinit</code> 调用 <code>inituvm</code> 把该二进制复制到新进程的内存中，<code>inituvm</code> 分配一页物理内存，把虚拟地址零映射到该内存，并把二进制复制到这一页 <span class="ln">(1886)</span>。</p><p>然后 <code>userinit</code> 用初始用户模式状态设置陷阱帧 <span class="ln">(0602)</span>：<code>cs</code> 寄存器包含 <code>SEG_UCODE</code> 段的段选择子，运行在特权级 <code>DPL_USER</code>（即用户模式而非内核模式）；类似地，<code>ds</code>、<code>es</code> 和 <code>ss</code> 使用 <code>SEG_UDATA</code>，特权级为 <code>DPL_USER</code>。<code>eflags</code> 的 <code>FL_IF</code> 位被置位，以允许硬件中断；我们将在 <a href="./ch3">第 3 章</a> 重新审视这一点。</p><p>栈指针 <code>esp</code> 被设为进程最大的有效虚拟地址 <code>p-&gt;sz</code>。指令指针被设为 initcode 的入口点，即地址 0。</p><p>函数 <code>userinit</code> 把 <code>p-&gt;name</code> 设为 <code>initcode</code>，主要是为了调试。设置 <code>p-&gt;cwd</code> 则设定进程的当前工作目录；我们将在 <a href="./ch6">第 6 章</a> 详细研究 <code>namei</code>。</p><p>进程初始化完成后，<code>userinit</code> 把 <code>p-&gt;state</code> 设为 <code>RUNNABLE</code>，把它标记为可调度。</p><h2 id="ch1-s7" tabindex="-1">代码：运行第一个进程 <a class="header-anchor" href="#ch1-s7" aria-label="Permalink to &quot;代码：运行第一个进程 {#ch1-s7}&quot;">​</a></h2><p>现在第一个进程的状态已经准备好，是时候运行它了。<code>main</code> 调用 <code>userinit</code> 之后，<code>mpmain</code> 调用 <code>scheduler</code> 开始运行进程 <span class="ln">(1257)</span>。<code>Scheduler</code> <span class="ln">(2758)</span> 寻找 <code>p-&gt;state</code> 为 <code>RUNNABLE</code> 的进程，只有一个：<code>initproc</code>。它把每 CPU 变量 <code>proc</code> 设为找到的进程，并调用 <code>switchuvm</code> 告诉硬件开始使用目标进程的页表 <span class="ln">(1879)</span>。在内核中执行时切换页表之所以可行，是因为 <code>setupkvm</code> 使所有进程的页表对内核代码和数据具有相同的映射。<code>switchuvm</code> 还建立一个任务状态段 <code>SEG_TSS</code>，指示硬件在该进程的内核栈上执行系统调用和中断。我们将在 <a href="./ch3">第 3 章</a> 重新审视任务状态段。</p><p><code>scheduler</code> 现在把 <code>p-&gt;state</code> 设为 <code>RUNNING</code>，并调用 <code>swtch</code> 执行到目标进程内核线程的上下文切换。<code>swtch</code> 首先保存当前寄存器。当前上下文不是进程，而是一个特殊的每 CPU 调度器上下文，因此 <code>scheduler</code> 让 <code>swtch</code> 把当前硬件寄存器保存到每 CPU 存储（<code>cpu-&gt;scheduler</code>）中，而不是保存到任何进程的内核线程上下文中。然后 <code>swtch</code> 把目标内核线程（<code>p-&gt;context</code>）保存的寄存器装入 x86 硬件寄存器，包括栈指针和指令指针。我们将在 <a href="./ch5">第 5 章</a> 更详细地研究 <code>swtch</code>。最后的 <code>ret</code> 指令从栈上弹出目标进程的 <code>eip</code>，完成上下文切换。现在处理器正运行在进程 <code>p</code> 的内核栈上。</p><p><code>Allocproc</code> 先前已把 <code>initproc</code> 的 <code>p-&gt;context-&gt;eip</code> 设为 <code>forkret</code>，因此 <code>ret</code> 开始执行 <code>forkret</code>。在第一次调用时（也就是这一次），<code>forkret</code> <span class="ln">(2853)</span> 运行一些初始化函数，这些函数不能从 <code>main</code> 中运行，因为它们必须在一个拥有自己内核栈的常规进程上下文中运行。然后 <code>forkret</code> 返回。<code>Allocproc</code> 已经安排好：<code>p-&gt;context</code> 被弹出后栈顶的字是 <code>trapret</code>，所以现在 <code>trapret</code> 开始执行，<code>esp</code> 被设为 <code>p-&gt;tf</code>。<code>Trapret</code> <span class="ln">(3324)</span> 使用 pop 指令从陷阱帧 <span class="ln">(0602)</span> 恢复寄存器，正如 <code>swtch</code> 对内核上下文所做的那样：<code>popal</code> 恢复通用寄存器，然后 <code>popl</code> 指令恢复 <code>gs</code>、<code>fs</code>、<code>es</code> 和 <code>ds</code>。<code>addl</code> 跳过 <code>trapno</code> 和 <code>errcode</code> 这两个字段。最后，<code>iret</code> 指令从栈上弹出 <code>cs</code>、<code>eip</code>、<code>flags</code>、<code>esp</code> 和 <code>ss</code>。陷阱帧的内容已被转移到 CPU 状态，因此处理器在陷阱帧中指定的 <code>eip</code> 处继续执行。对 <code>initproc</code> 来说，那就是虚拟地址零，即 <code>initcode.S</code> 的第一条指令。</p><p>此时，<code>eip</code> 的值为零，<code>esp</code> 的值为 4096。它们是进程地址空间中的虚拟地址。处理器的分页硬件把它们转换为物理地址。<code>allocuvm</code> 已经建立了进程的页表，使虚拟地址零指向为该进程分配的物理内存，并设置了一个标志（<code>PTE_U</code>），告诉分页硬件允许用户代码访问该内存。<code>userinit</code> <span class="ln">(2533)</span> 把 <code>cs</code> 的低位设置为在 CPL=3 下运行进程的用户代码，这意味着用户代码只能使用设置了 <code>PTE_U</code> 的页，并且不能修改 <code>cr3</code> 等敏感硬件寄存器。因此，进程被限制为只能使用自己的内存。</p><h2 id="ch1-s8" tabindex="-1">第一次系统调用：exec <a class="header-anchor" href="#ch1-s8" aria-label="Permalink to &quot;第一次系统调用：exec {#ch1-s8}&quot;">​</a></h2><p>既然我们已经看到内核如何为进程提供强隔离，接下来看看用户级进程如何重新进入内核，以请求它自己无法完成的服务。</p><p><code>initcode.S</code> 的第一个动作是调用 <code>exec</code> 系统调用。正如我们在 <a href="./ch0">第 0 章</a> 看到的，<code>exec</code> 用新程序替换当前进程的内存和寄存器，但保留文件描述符、进程 ID 和父进程不变。</p><p><code>Initcode.S</code> <span class="ln">(8409)</span> 首先在栈上压入三个值——<code>$argv</code>、<code>$init</code> 和 <code>$0</code>——然后设置 <code>eax</code> 为 <code>SYS_exec</code> 并执行 <code>int</code> <code>T_SYSCALL</code>：它在请求内核运行 <code>exec</code> 系统调用。如果一切顺利，<code>exec</code> 永不返回：它开始运行由 <code>$init</code> 命名的程序，<code>$init</code> 是指向以 NUL 结尾的字符串 <code>/init</code> 的指针 <span class="ln">(8422-8424)</span>。另一个参数是命令行参数数组 <code>argv</code>；数组末尾的零标记它的结束。如果 <code>exec</code> 失败并返回，initcode 就循环调用 <code>exit</code> 系统调用，而后者绝对不应返回 <span class="ln">(8416-8420)</span>。</p><p>这段代码手工构造第一次系统调用，使它看起来像一次普通的系统调用，我们将在 <a href="./ch3">第 3 章</a> 看到这一点。和前面一样，这种设置避免为第一个进程（这里是它的第一次系统调用）做特殊处理，而是复用 xv6 为常规运行必须提供的代码。</p><p><a href="./ch2">第 2 章</a> 将详细讨论 <code>exec</code> 的实现，但概括地说，它用从文件系统加载的 <code>/init</code> 二进制替换 <code>initcode</code>。现在 <code>initcode</code> <span class="ln">(8400)</span> 的使命完成，进程将改为运行 <code>/init</code>。<code>Init</code> <span class="ln">(8510)</span> 在需要时创建一个新的控制台设备文件，然后把它作为文件描述符 0、1、2 打开。接着它进入循环：启动一个控制台 shell，处理孤儿僵尸进程直到 shell 退出，然后重复。系统就此启动。</p><h2 id="ch1-s9" tabindex="-1">现实世界 <a class="header-anchor" href="#ch1-s9" aria-label="Permalink to &quot;现实世界 {#ch1-s9}&quot;">​</a></h2><p>在现实世界中，宏内核和微内核都能见到。许多 Unix 内核是宏内核。例如，Linux 有一个宏内核，尽管某些操作系统功能以用户级服务器运行（例如窗口系统）。L4、Minix、QNX 等内核组织为带服务器的微内核，并在嵌入式环境中得到了广泛部署。</p><p>大多数操作系统都采用了进程概念，大多数进程看起来与 xv6 的进程相似。真实操作系统会用显式的空闲链表在常数时间内找到空闲的 <code>proc</code> 结构，而不是像 <code>allocproc</code> 那样线性搜索；xv6 为了简单而使用线性扫描（这是众多简化中的第一个）。</p><h2 id="ch1-s10" tabindex="-1">练习 <a class="header-anchor" href="#ch1-s10" aria-label="Permalink to &quot;练习 {#ch1-s10}&quot;">​</a></h2><ol><li><p>在 swtch 处设置断点。用 gdb 的 <code>stepi</code> 单步执行 ret 到 <code>forkret</code>，然后用 gdb 的 <code>finish</code> 前进到 <code>trapret</code>，再用 <code>stepi</code> 直到进入虚拟地址零处的 <code>initcode</code>。</p></li><li><p><code>KERNBASE</code> 限制了单个进程可用的内存量，这在拥有完整 4 GB RAM 的机器上可能很恼人。提高 <code>KERNBASE</code> 会让进程使用更多内存吗？</p></li></ol>',77)])])}const _=c(i,[["render",r]]);export{u as __pageData,_ as default};
